    "campaign_id": "Provide the campaign_id for this launch",
    "sec_ticket": "Provide if the selected campaign requires one",
    "send_window_today": "Preferred send time today (e.g., 2–4 PM local)",
    "cta_url": "Destination link for the main CTA",
    "key_points": "Top 2–3 benefits or announcements to feature"
